    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    max_len = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] - arr[j] == diff:
                dp[i][j] = dp[i + 1][j - 1] + 1
