def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    longest = 0
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = 2
            longest = 2
    for k in range(3, n+1):
        for i in range(n-k+1):
            j = i + k - 1
            if s[i] == s[j] and dp[i+1][j-1] == 1:
                dp[i][j] = dp[i+1][j-1] + 2
                longest = max(longest, dp[i][j])
    return longest

