def count_equilateral_triangles(a, b, c):
    # Calculate the area of the triangle
    s = (a + b + c) / 2
    area = (s*(s-a)*(s-b)*(s-c)) ** 0.5
    # Calculate the number of equilateral triangles that can be formed
    num_triangles = 1
    for i in range(1, a):
        if s**2 <= area:
            num_triangles += 1
            break
    for i in range(1, b):
        if s**2 <= area:
            num_triangles += 1
            break
    for i in range(1, c):
        if s**2 <= area:
            num_triangles += 1
            break
    return num_triangles

