def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for i in range(n-1):
        j = n-1
        while s[i] == s[j]:
            j -= 1
        dp[i][j] = i + 1
    for i in range(n-1):
        for j in range(n-1):
            if s[i] == s[j] and i + 1 == j:
                dp[i][j] = i + 1
            elif s[i] == s[j] and dp[i+1][j-1] > dp[i][j]:
                dp[i][j] = dp[i+1][j-1]
    return dp[0][n-1]

