def max_profit(prices, k):
    if k == 0 or len(prices) == 0:
        return 0
    if k == 1:
        return max(prices)
    max_profit = 0
    for i in range(len(prices) - k + 1):
        current_profit = prices[i + k - 1] - prices[i]
        max_profit = max(max_profit, current_profit)
    return max_profit

